window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-37c066a424cb4708"]={"versions": [{"id": "FIG-37c066a424cb4708", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles AUTOSAR-Architektur- und Datenflussdiagramm (Kombination aus Schichtenmodell, Port-Verbindungen und BSW-internen Schnittstellenaufrufen). Das Diagramm verortet die Interaktion zur Berechnung und Bereitstellung von OBD-II-Readiness-Informationen (ISO 15031-5 / SAE J1979) zwischen der Application Layer (SW-Cs), der Run-Time Environment (RTE) und den Basissoftware-Modulen Dem (Diagnostic Event Manager) sowie Dcm (Diagnostic Communication Manager). Zweck ist die Veranschaulichung, wie Monitor-Operationen von Applikationskomponenten in OBD-Statusdaten für PID $01 und PID $41 überführt und für Diagnoseanfragen bereitgestellt werden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>SW-C 1, SW-C 2, SW-C 3</strong>: Software-Components der Applikationsschicht, die als Diagnosemonitore fungieren. Jede SW-C besitzt einen Required-Port (R-Port, Halbbogen-Symbol).</li>\n<li><strong>RTE (Run-Time Environment)</strong>: Vermittelnde Middleware-Schicht zwischen Applikationskomponenten und Basissoftware.</li>\n<li><strong>Dem (Diagnostic Event Manager)</strong>: BSW-Modul mit Provided-Ports (P-Ports, Kreis-im-Quadrat) für jede SW-C und internen Datenstrukturen/Puffern zur Aggregation der Event- und Readiness-Zustände.</li>\n<li><strong>Dcm (Diagnostic Communication Manager)</strong>: BSW-Modul zur Abwicklung externer Diagnosedienste mit Pufferstrukturen zur Aufbereitung von PID-Telemetriedaten.</li>\n<li><strong>Schnittstellen & Operationen</strong>:</li>\n<li><code>DiagnosticMonitor</code>: Client-Server-Port-Interface zwischen SW-Cs und Dem über die RTE.</li>\n<li><code>SetEventDisabled()</code>: Operation zur Deaktivierung eines Events/Monitors (dargestellt für SW-C 2).</li>\n<li><code>SetEventStatus()</code>: Operation zur Meldung des Überwachungsstatus (z. B. Passed/Failed, dargestellt für SW-C 3).</li>\n<li>SW-C 1 ist über dieselbe Port-Architektur angebunden.</li>\n<li>C-API-Schnittstellen zwischen Dem und Dcm (BSW-intern):</li>\n<li><code>Dem_DcmReadDataOfPID01()</code>: Funktionsaufruf des Dcm zum Auslesen der 4-Byte-Readiness-Daten seit Fehlerspeicherlöschung (PID $01).</li>\n<li><code>Dem_DcmReadDataOfPID41()</code>: Funktionsaufruf des Dcm zum Auslesen der 4-Byte-Readiness-Daten des aktuellen Fahrzyklus (PID $41).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Ereignis- und Statusüberwachung</strong>: SW-Cs führen Diagnoseprüfungen durch und rufen über die RTE Operationen des Interfaces <code>DiagnosticMonitor</code> auf. <code>SetEventStatus()</code> meldet Testergebnisse an das Dem, während <code>SetEventDisabled()</code> anzeigt, dass ein Monitor im aktuellen Fahrzyklus deaktiviert bzw. nicht durchführbar ist.</li>\n<li><strong>Zustandsberechnung im Dem</strong>: Das Dem empfängt die Aufrufe an seinen P-Ports, aktualisiert seine internen Zustandsmatrizen und aggregiert die Readiness-Bits der konfigurierten OBD-Überwachungsgruppen für PID $01 (kumuliert seit letztem Reset/Clear DTC) sowie PID $41 (bezogen auf den aktuellen Fahrzyklus).</li>\n<li><strong>Diagnoseabfrage</strong>: Bei Eintreffen einer externen OBD-Dienstabfrage (Service $01) liest der Dcm synchron über die APIs <code>Dem_DcmReadDataOfPID01()</code> und <code>Dem_DcmReadDataOfPID41()</code> die aufbereiteten Datenbytes aus dem Dem aus und überführt sie in den Antwortpuffer zur Übertragung an den Diagnosetester.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellentrennung</strong>: SW-Cs dürfen nicht direkt auf C-APIs des Dem zugreifen; die Anbindung muss zwingend über standardisierte AUTOSAR-Port-Schnittstellen (<code>DiagnosticMonitor</code>) via RTE erfolgen. Die Dem-Dcm-Interaktion erfolgt hingegen BSW-intern über direkte C-Funktionsaufrufe.</li>\n<li><strong>Readiness-Berechnung</strong>: Das Erreichen des Status „Completed“ für OBD-Readiness-Gruppen in PID $01/$41 erfordert qualifizierte Rückmeldungen (<code>PASSED</code> oder <code>FAILED</code>) über <code>SetEventStatus()</code>. Deaktivierungen über <code>SetEventDisabled()</code> wirken sich auf die Zuordnung „supported / not supported“ bzw. die Testbarkeit im aktuellen Zyklus aus.</li>\n<li><strong>Pufferverwaltung</strong>: Dem und Dcm synchronisieren OBD-Readinessdaten über standardisierte 4-Byte-Puffer. Integratoren müssen sicherstellen, dass alle emissionsrelevanten Events den entsprechenden Dem-OBD-Readiness-Gruppen (z. B. Misfire, Fuel System, Catalyst) korrekt parametriert zugeordnet sind.</li>\n</ul>"}, {"id": "FIG-4aa32dd4de2791c1", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles AUTOSAR-Architektur- und Datenflussdiagramm (Kombination aus Schichtenmodell, Port-Verbindungen und BSW-internen Schnittstellenaufrufen). Das Diagramm verortet die Interaktion zur Berechnung und Bereitstellung von OBD-II-Readiness-Informationen (ISO 15031-5 / SAE J1979) zwischen der Application Layer (SW-Cs), der Run-Time Environment (RTE) und den Basissoftware-Modulen Dem (Diagnostic Event Manager) sowie Dcm (Diagnostic Communication Manager). Zweck ist die Veranschaulichung, wie Monitor-Operationen von Applikationskomponenten in OBD-Statusdaten für PID $01 und PID $41 überführt und für Diagnoseanfragen bereitgestellt werden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>SW-C 1, SW-C 2, SW-C 3</strong>: Software-Components der Applikationsschicht, die als Diagnosemonitore fungieren. Jede SW-C besitzt einen Required-Port (R-Port, Halbbogen-Symbol).</li>\n<li><strong>RTE (Run-Time Environment)</strong>: Vermittelnde Middleware-Schicht zwischen Applikationskomponenten und Basissoftware.</li>\n<li><strong>Dem (Diagnostic Event Manager)</strong>: BSW-Modul mit Provided-Ports (P-Ports, Kreis-im-Quadrat) für jede SW-C und internen Datenstrukturen/Puffern zur Aggregation der Event- und Readiness-Zustände.</li>\n<li><strong>Dcm (Diagnostic Communication Manager)</strong>: BSW-Modul zur Abwicklung externer Diagnosedienste mit Pufferstrukturen zur Aufbereitung von PID-Telemetriedaten.</li>\n<li><strong>Schnittstellen & Operationen</strong>:</li>\n<li><code>DiagnosticMonitor</code>: Client-Server-Port-Interface zwischen SW-Cs und Dem über die RTE.</li>\n<li><code>SetEventDisabled()</code>: Operation zur Deaktivierung eines Events/Monitors (dargestellt für SW-C 2).</li>\n<li><code>SetEventStatus()</code>: Operation zur Meldung des Überwachungsstatus (z. B. Passed/Failed, dargestellt für SW-C 3).</li>\n<li>SW-C 1 ist über dieselbe Port-Architektur angebunden.</li>\n<li>C-API-Schnittstellen zwischen Dem und Dcm (BSW-intern):</li>\n<li><code>Dem_DcmReadDataOfPID01()</code>: Funktionsaufruf des Dcm zum Auslesen der 4-Byte-Readiness-Daten seit Fehlerspeicherlöschung (PID $01).</li>\n<li><code>Dem_DcmReadDataOfPID41()</code>: Funktionsaufruf des Dcm zum Auslesen der 4-Byte-Readiness-Daten des aktuellen Fahrzyklus (PID $41).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Ereignis- und Statusüberwachung</strong>: SW-Cs führen Diagnoseprüfungen durch und rufen über die RTE Operationen des Interfaces <code>DiagnosticMonitor</code> auf. <code>SetEventStatus()</code> meldet Testergebnisse an das Dem, während <code>SetEventDisabled()</code> anzeigt, dass ein Monitor im aktuellen Fahrzyklus deaktiviert bzw. nicht durchführbar ist.</li>\n<li><strong>Zustandsberechnung im Dem</strong>: Das Dem empfängt die Aufrufe an seinen P-Ports, aktualisiert seine internen Zustandsmatrizen und aggregiert die Readiness-Bits der konfigurierten OBD-Überwachungsgruppen für PID $01 (kumuliert seit letztem Reset/Clear DTC) sowie PID $41 (bezogen auf den aktuellen Fahrzyklus).</li>\n<li><strong>Diagnoseabfrage</strong>: Bei Eintreffen einer externen OBD-Dienstabfrage (Service $01) liest der Dcm synchron über die APIs <code>Dem_DcmReadDataOfPID01()</code> und <code>Dem_DcmReadDataOfPID41()</code> die aufbereiteten Datenbytes aus dem Dem aus und überführt sie in den Antwortpuffer zur Übertragung an den Diagnosetester.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellentrennung</strong>: SW-Cs dürfen nicht direkt auf C-APIs des Dem zugreifen; die Anbindung muss zwingend über standardisierte AUTOSAR-Port-Schnittstellen (<code>DiagnosticMonitor</code>) via RTE erfolgen. Die Dem-Dcm-Interaktion erfolgt hingegen BSW-intern über direkte C-Funktionsaufrufe.</li>\n<li><strong>Readiness-Berechnung</strong>: Das Erreichen des Status „Completed“ für OBD-Readiness-Gruppen in PID $01/$41 erfordert qualifizierte Rückmeldungen (<code>PASSED</code> oder <code>FAILED</code>) über <code>SetEventStatus()</code>. Deaktivierungen über <code>SetEventDisabled()</code> wirken sich auf die Zuordnung „supported / not supported“ bzw. die Testbarkeit im aktuellen Zyklus aus.</li>\n<li><strong>Pufferverwaltung</strong>: Dem und Dcm synchronisieren OBD-Readinessdaten über standardisierte 4-Byte-Puffer. Integratoren müssen sicherstellen, dass alle emissionsrelevanten Events den entsprechenden Dem-OBD-Readiness-Gruppen (z. B. Misfire, Fuel System, Catalyst) korrekt parametriert zugeordnet sind.</li>\n</ul>"}], "trans": [{"from": "FIG-37c066a424cb4708", "to": "FIG-4aa32dd4de2791c1", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
